import React , {useEffect, useState} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId, updStore, hasWritePrivilege, ObjectKeys, getLabelTranslate, blobfromArray, parseDateMMDDYY, CapitalizeString, num2Word } from "../../../stores/Utils";

import { useNavigate } from "react-router";
import { CloseModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt, TextInput_Cmpt } from "../../../components";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import { getall_provider } from "../../ProvidersCustomers/services/server_fetching";
import { Invoice2Pdf, InvoiceLabelsPdf1X3 } from "../services/export_service";

import DropDwnPickerSearchComponent from "../../../components/DropDwnPickerSearch";
import { getProductByQuery } from "../../Inventory/services/server_fetching";
import { getEmployeeByQuery, getProviderByQuery } from "../../Employees/services/server_fetching";
import { DateCalComponent_Cmpt } from "../../Inventory";
import { ManualCheck2Print } from "../../Inventory/services/export_service";


const Svg = SvgIcon_Cmpt();
const TextInput = TextInput_Cmpt();
const DateCalComponent =DateCalComponent_Cmpt();

const frmNm = "check2Vmp"


const ViewInvoice  = ({ data, item }) => {

	const [obs, set_obs] = useState(0);


	
	useEffect(() => {
		
		if(!(getStore("providers_ids"))){
			getall_provider(updObs);
		}

		if(!getStore("providers_ids")){
			//Log$$("fetching products")
			getall_provider(updObs);
		}
		
		
		get_balances_by_type("global_accounts","global_account_params",updObs);
		updObs();
		//get_inventory_by_prod(item.productId,updObs)
	},[]);

	const updObs =  () => {
		set_obs(gen16CodeId())
	}




	const navigate = useNavigate();

	const close =  (element) => {
		CloseModal({id:data.modalID});
		
	}
	

	
	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};



	const printInvoice =  () => {
		ManualCheck2Print(getStore(frmNm))

		
	}

	const printInvoiceLbl =  () => {
		
	}


	const updlocDrop =  (f,v) => {
		updFrm(f,v.id);
		updFrm("name2Check",v.label);
	}
	

	let amountTx = getStore(frmNm)?.["amount"] ? CapitalizeString( num2Word(getStore(frmNm)?.["amount"])) : ""

	return (
		<div style={{
			maxHeight: "94vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 30px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect gSansFont">
					{ "Manual Check" } 
				</p>
				
				<div className="flexSpace"/>
				
				<div className="icon_print" onClick={printInvoice}>
					<Svg name={"printer"} color={"var(--hrm_palette-inverse-background-b)"}/>
				</div>
			</div>
			<div className="_dsplFlx spaceAround flxWrp"  > 
				<div className="flexSpace"/>
				<div className="_dsplFlx spaceAround"  style={{marginTop: 23}}>
					<DropDwnPickerSearchComponent 
						init={getStore(frmNm)?.provider2CheckId}
						lbl_empty={"Cliente o Provedor"} 
						func={getProviderByQuery}
						onSelect={(e)=>updlocDrop("provider2CheckId",e)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"280px"}
					/>
				</div>
				<div className="flexSpace"/>
				<div className="_dsplFlx spaceAround"  style={{marginTop: 23}}>
					<DropDwnPickerSearchComponent 
						init={getStore(frmNm)?.employee2CheckId}
						lbl_empty={"Empleados"} 
						func={getEmployeeByQuery}
						onSelect={(e)=>updlocDrop("employee2CheckId",e)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"280px"}
					/>
				</div>
				<div className="flexSpace"/>
				
			</div>
			<div className="_dsplFlx spaceAround flxWrp " style={{margin:"20px 0"}}>

				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["name2Check"]} 
					label={"Name"} 
					width={520} 
					updChanges={(e)=>updFrm("name2Check",e)}
				/>
				<div className="flexSpace"/>
			</div>
			<div className="_dsplFlx spaceAround flxWrp " >
				<div className="flexSpace"/>
				<DateCalComponent 
					label={getLabelTranslate(3)}
					init={getStore(frmNm)?.["date"]} 
					updDate={(e)=>updFrm("date",e)} 
				/>
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["amount"]} 
					label={"Amount"} 
					width={120} 
					type={"number"}
					updChanges={(e)=>updFrm("amount",e)}
				/>
				<div className="flexSpace"/>
			</div>
			<div className="_dsplFlx spaceAround flxWrp " >
				
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["memo"]} 
					label={"Memo"} 
					width={520} 
					updChanges={(e)=>updFrm("memo",e)}
				/>
				<div className="flexSpace"/>
			</div>
			<div className=" spaceAround flxWrp chckFrm" style={{margin:"20px "}}>

				<div className="_dsplFlx " style={{marginBottom: 8}}>
					<div className="check_itm"  >
					{getStore(frmNm)?.amount?"$"+(getStore(frmNm)?.amount*1)?.toFixed(2):""}
					</div>
					<div className="flexSpace"/>
					<div className="check_itm"  >
					{getStore(frmNm)?.date? parseDateMMDDYYYY(getStore(frmNm)?.date) : ""}
					</div>
				</div>
				<div className="_dsplFlx " style={{marginBottom: 8}}>
					<div className="check_itm"  >
					{amountTx}
					</div>
				</div>
				<div className="_dsplFlx " style={{marginBottom: 8}}>
					<div className="check_itm"  >
						{getStore(frmNm)?.name2Check}
					</div>
				</div>
				<div className="_dsplFlx " style={{marginBottom: 8}}>
					<div className="check_itm"  >
						memo: {getStore(frmNm)?.memo}
					</div>
				</div>
			</div>

		</div>
	);
};

export default ViewInvoice;









const ListingProducts  = ({ element, idKey, close }) => {
	let product = getStore("products_ids")?.[element?.product];

	let amount = element.qty*1 ?element.qty*1*element.salePrice:0;
	return (
		<div className="_dsplFlx hdr_bar">
			<div className="tr_bar_70 gSansFont" style={{textAlign:"left", paddingLeft: 14}}>
				{product?.name}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element.qty)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{amount?.toFixed(2)}
			</div>
			
		</div>
	)

}


const ListingExtras  = ({ element, idKey, close }) => {


	return (
		<div className="_dsplFlx hdr_bar">
			<div className="tr_bar_70  gSansFont" style={{textAlign:"left", paddingLeft: 14}}>
				{element?.description}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont" >
				{(element.qty*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element.qty*1)?((element.qty*1)*element.salePrice*1)?.toFixed(2):""}
			</div>
			
		</div>
	)

}


